//! Checks the Rust RNG and soft-float code against observations of the original
//! `Game.dll` 1.26a (see `data.rs`, generated by `tools/emu/gen_vectors.py`).
//!
//! The RNG table is read from the file named by the `GAME_DLL` environment
//! variable. When it is not set, each test prints a note and returns early.

mod data;

use sim::softfloat;
use sim::{Rng, RngTable, Streams, STREAM_COUNT};

/// Loads the permutation table from `GAME_DLL`, or `None` (with a note) if unset.
fn table() -> Option<RngTable> {
    let Ok(path) = std::env::var("GAME_DLL") else {
        eprintln!("GAME_DLL not set: skipping test that needs the Game.dll RNG table");
        return None;
    };
    let bytes = std::fs::read(&path).unwrap_or_else(|e| panic!("reading GAME_DLL={path}: {e}"));
    Some(RngTable::from_game_dll(&bytes).expect("RNG table in GAME_DLL"))
}

fn state(a: u32, b: u32) -> Rng {
    Rng { a, b }
}

fn stream_state(pairs: &[(u32, u32)]) -> Vec<Rng> {
    assert_eq!(pairs.len(), STREAM_COUNT);
    pairs.iter().map(|&(a, b)| state(a, b)).collect()
}

#[test]
fn seeder_matches_original() {
    for &(s, a, b) in data::SEEDER {
        assert_eq!(Rng::seeded(s), state(a, b), "seed {s:#010x}");
    }
}

#[test]
fn step_matches_original() {
    let Some(t) = table() else { return };
    for &(a, b, out, a2, b2) in data::STEP {
        let mut rng = state(a, b);
        assert_eq!(
            rng.next_u32(&t),
            out,
            "step output from ({a:#010x}, {b:#010x})"
        );
        assert_eq!(rng, state(a2, b2), "step state from ({a:#010x}, {b:#010x})");
    }
}

#[test]
fn get_random_int_matches_original() {
    let Some(t) = table() else { return };
    for &(a, b, lo, hi, ret, a2, b2) in data::GET_RANDOM_INT {
        let mut rng = state(a, b);
        assert_eq!(
            rng.random_int(&t, lo, hi),
            ret,
            "GetRandomInt({lo}, {hi}) from ({a:#010x}, {b:#010x})"
        );
        assert_eq!(rng, state(a2, b2), "state after GetRandomInt({lo}, {hi})");
    }
}

#[test]
fn get_random_real_matches_original() {
    let Some(t) = table() else { return };
    for &(a, b, fa, fb, ret, a2, b2) in data::GET_RANDOM_REAL {
        let mut rng = state(a, b);
        let got = rng.random_real(&t, f32::from_bits(fa), f32::from_bits(fb));
        assert_eq!(
            got.to_bits(),
            ret,
            "GetRandomReal({:e}, {:e}) from ({a:#010x}, {b:#010x})",
            f32::from_bits(fa),
            f32::from_bits(fb)
        );
        assert_eq!(rng, state(a2, b2), "state after GetRandomReal");
    }
}

#[test]
fn get_random_real_uniform_bits_match_original() {
    let Some(t) = table() else { return };
    for &(a, b, fa, fb, ret, a2, b2) in data::GET_RANDOM_REAL_UNIFORM {
        let mut rng = state(a, b);
        let got = rng.random_real(&t, f32::from_bits(fa), f32::from_bits(fb));
        assert_eq!(
            got.to_bits(),
            ret,
            "GetRandomReal({fa:#010x}, {fb:#010x}) from ({a:#010x}, {b:#010x})"
        );
        assert_eq!(
            rng,
            state(a2, b2),
            "state after GetRandomReal({fa:#010x}, {fb:#010x})"
        );
    }
}

#[test]
fn set_random_seed_matches_original() {
    let Some(t) = table() else { return };
    for &(s, g_a, g_b, streams) in data::SET_RANDOM_SEED {
        let mut all = Streams::default();
        all.set_random_seed(&t, s);
        assert_eq!(
            all.global,
            state(g_a, g_b),
            "global after SetRandomSeed({s:#010x})"
        );
        for (k, want) in stream_state(streams).into_iter().enumerate() {
            assert_eq!(
                all.stream(k),
                want,
                "stream {k} after SetRandomSeed({s:#010x})"
            );
        }
    }
}

#[test]
fn stream_init_matches_original() {
    let Some(t) = table() else { return };
    for &(x, streams) in data::STREAM_INIT {
        let mut all = Streams::default();
        all.init_streams(&t, x);
        assert_eq!(
            all.global,
            Rng::default(),
            "init_streams must not touch the global generator"
        );
        for (k, want) in stream_state(streams).into_iter().enumerate() {
            assert_eq!(all.stream(k), want, "stream {k} after init from {x:#010x}");
        }
    }
}

#[test]
fn soft_float_matches_original() {
    for &(x, y, r) in data::SOFT_ADD {
        assert_eq!(softfloat::add(x, y), r, "add({x:#010x}, {y:#010x})");
    }
    for &(x, y, r) in data::SOFT_SUB {
        assert_eq!(softfloat::sub(x, y), r, "sub({x:#010x}, {y:#010x})");
    }
    for &(x, y, r) in data::SOFT_MUL {
        assert_eq!(softfloat::mul(x, y), r, "mul({x:#010x}, {y:#010x})");
    }
    for &(x, y, r) in data::SOFT_UNIFORM_ADD {
        assert_eq!(softfloat::add(x, y), r, "add({x:#010x}, {y:#010x})");
    }
    for &(x, y, r) in data::SOFT_UNIFORM_SUB {
        assert_eq!(softfloat::sub(x, y), r, "sub({x:#010x}, {y:#010x})");
    }
    for &(x, y, r) in data::SOFT_UNIFORM_MUL {
        assert_eq!(softfloat::mul(x, y), r, "mul({x:#010x}, {y:#010x})");
    }
}
